            answer:
              "f is polynomial ⇒ continuous and differentiable. f(1) = 1 − 4 + 3 = 0, f(3) = 9 − 12 + 3 = 0 ⇒ f(1) = f(3). f'(x) = 2x − 4. Set 2x − 4 = 0 ⇒ x = 2 in (1,3). Thus Rolle’s Theorem is verified.",
